package com.arjunren.loan.dto;
import com.arjunren.loan.domain.*; import com.arjunren.loan.entity.*; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.Instant; import java.util.List;
public final class Dtos{private Dtos(){}public record RegisterRequest(@NotBlank@Size(min=2,max=120)String name,@Email@NotBlank String email,@NotBlank@Size(min=12,max=72)String password){}public record LoginRequest(@Email@NotBlank String email,@NotBlank@Size(max=72)String password){}public record UserResponse(Long id,String email,String name,Role role){public static UserResponse of(AppUser u){return new UserResponse(u.getId(),u.getEmail(),u.getName(),u.getRole());}}public record TokenResponse(String accessToken,String tokenType,Instant expiresAt,UserResponse user){}public record ApplyRequest(@DecimalMin("100.00")@Digits(integer=17,fraction=2)BigDecimal principal,@Min(1)@Max(360)int termMonths,@NotBlank@Size(max=500)String purpose){}public record ApproveRequest(@DecimalMin("0.0000")@DecimalMax("100.0000")@Digits(integer=3,fraction=4)BigDecimal annualInterestRate){}public record RejectRequest(@NotBlank@Size(max=500)String reason){}public record RepayRequest(@DecimalMin("0.01")@Digits(integer=17,fraction=2)BigDecimal amount){}public record LoanResponse(Long id,Long customerId,String customerName,BigDecimal principal,int termMonths,String purpose,LoanStatus status,BigDecimal annualInterestRate,BigDecimal totalRepayable,BigDecimal outstandingBalance,String rejectionReason,Instant createdAt,Instant updatedAt){public static LoanResponse of(LoanApplication l){return new LoanResponse(l.getId(),l.getCustomer().getId(),l.getCustomer().getName(),l.getPrincipal(),l.getTermMonths(),l.getPurpose(),l.getStatus(),l.getAnnualInterestRate(),l.getTotalRepayable(),l.getOutstandingBalance(),l.getRejectionReason(),l.getCreatedAt(),l.getUpdatedAt());}}public record RepaymentResponse(Long id,Long loanId,BigDecimal amount,String reference,Instant paidAt){public static RepaymentResponse of(Repayment r){return new RepaymentResponse(r.getId(),r.getLoanId(),r.getAmount(),r.getReference(),r.getPaidAt());}}public record PageResponse<T>(List<T>items,int page,int size,long totalElements,int totalPages){}
}

